window.DEX_DATA["sources:backport-87c480a4dbea4776"]={"json":{"skins":[{"filename":"tesla.png"}],"names":[{"name":"尼古拉·特斯拉"}],"chat":[{"lines":[{"text":"一盏红石灯接着一盏，让世界亮起来！"}]},{"lines":[{"text":"洛托姆能控制电子设备？真是惊人的消息！"}]},{"lines":[{"text":"拿电属性宝可梦给电器供电的人也太过分了。"},{"text":"谁会忍心这样使唤自己的宝可梦啊！"}]},{"lines":[{"text":"你知道什么好用的红石电路吗？"},{"text":"我只是在给城市供电，又不是解决世界和平。"}]}]}};
